add_action( 'woocommerce_thankyou', 'perfectpixel_include_page_in_thank_you', 5 );

function perfectpixel_include_page_in_thank_you( $order_id ) {
	$page = get_post( (int) '{{thankyou_page_content_id}}' );
	if ( ! $page || 'publish' !== $page->post_status ) {
		return;
	}
	echo '<div class="perfectpixel-thankyou-content">' . apply_filters( 'the_content', $page->post_content ) . '</div>'; // phpcs:ignore WordPress.Security.EscapeOutput -- Page content.
}
